class Node:
  def __init__(self, data, pri):
    self.data = data
    self.next = None
    self.pri = pri


class Queue:
  def __init__(self):
    self.front = None
    self.tail = None

  def enQueue(self, num, pri):
    new = Node(num, pri)
    if self.tail == None:
      self.front = self.tail = new
    elif self.front == self.tail:
      if self.front.pri <= new.pri:
        self.front.next = new
        self.tail = new
      else:
        self.front = new
        self.front.next = self.tail
    else:
      cur = self.front
      if new.pri < self.front.pri:
        new.next = self.front
        self.front = new
        return
      while True:
        if (cur.pri <= new.pri) and (new.pri < cur.next.pri):
          new.next = cur.next
          cur.next = new
          return
        elif cur == self.tail:
          self.tail.next = new
          self.tail = new
          return
        else:
          cur = cur.next


  def deQueue(self):
    if self.front == None:
      print("dequeue FAIL: Queue is empty.")
      return None
    elif self.front == self.tail:
      data = self.front.data
      self.front = self.tail = None
      return data
    else:
      data = self.front.data
      self.front = self.front.next
      return data

  def printQueue(self):
